import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { consumeGmailState } from "@/lib/gmail-oauth";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

export const Route = createFileRoute("/gmail/callback")({
  component: GmailCallbackPage,
});

function GmailCallbackPage() {
  const navigate = useNavigate();

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get("code");
    const error = params.get("error");
    const state = params.get("state");

    if (error) {
      toast.error("Gmail connection cancelled.");
      navigate({ to: "/settings" });
      return;
    }
    if (!code || !consumeGmailState(state)) {
      toast.error("Invalid Gmail callback. Please try connecting again.");
      navigate({ to: "/settings" });
      return;
    }

    async function exchangeCode() {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) { navigate({ to: "/auth" }); return; }

      const { data, error: fnError } = await supabase.functions.invoke("gmail-oauth", {
        body: { code },
      });

      if (fnError || data?.error) {
        toast.error(data?.error ?? "Failed to connect Gmail. Please try again.");
        navigate({ to: "/settings" });
        return;
      }

      toast.success(`Gmail connected: ${data.email}`);
      navigate({ to: "/settings" });
    }

    void exchangeCode();
  }, [navigate]);

  return (
    <div className="flex min-h-screen items-center justify-center">
      <div className="text-center">
        <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
        <p className="mt-4 text-sm text-muted-foreground">Connecting your Gmail...</p>
      </div>
    </div>
  );
} 
